<script setup lang="ts">
import { Monitor, SlidersHorizontal, LogOut, ArrowUpRight, Check, Trash2, Eye, ShieldCheck, Pause, Play, Radio, X } from 'lucide-vue-next'
import { defaults, type Settings, type Krathong } from '#shared/models'
const {state,connected}=useLive();const logged=ref(false);const password=ref('');const loginError=ref('');const error=ref('');const notice=ref('');const busy=ref(false);const draft=ref<Settings>({...defaults});const tab=ref('scene');const items=ref<Krathong[]>([]);const confirmClear=ref(false);const origin=ref('');const saving=ref(false);const checking=ref(true)
const pending=computed(()=>items.value.filter(k=>k.status==='pending'));const guestUrl=computed(()=>draft.value.guestUrl||origin.value)
const sliders=[{key:'size',label:'ขนาดกระทง',hint:'ปรับให้เหมาะกับระยะมองและขนาดจอ',min:.4,max:2,step:.05,unit:'×'},{key:'speed',label:'ความเร็วกระทง',hint:'ความเร็วที่กระทงลอยผ่านหน้าจอ',min:.1,max:3,step:.1,unit:'×'},{key:'sceneSpeed',label:'ความเร็วฉากหลัง',hint:'การเคลื่อนตัวของแนวทิวเขา',min:0,max:3,step:.1,unit:'×'},{key:'waterSpeed',label:'ความเร็วสายน้ำ',hint:'จังหวะระลอกคลื่นบนผิวน้ำ',min:.1,max:3,step:.1,unit:'×'},{key:'brightness',label:'ความสว่างฉาก',hint:'ปรับตามแสงภายในสถานที่',min:.3,max:1.5,step:.05,unit:'×'},{key:'maxVisible',label:'จำนวนกระทงบนจอ',hint:'แสดงกระทงล่าสุดตามจำนวนที่กำหนด',min:1,max:100,step:1,unit:' กระทง'}] as const
let saveTimer:ReturnType<typeof setTimeout>;let refreshTimer:ReturnType<typeof setInterval>;let queued=false
async function refresh(){try{const r=await $fetch<any>('/api/admin/state');logged.value=true;items.value=r.krathongs;if(!saving.value&&!queued)draft.value={...r.settings}}catch{logged.value=false}finally{checking.value=false}}
onMounted(()=>{origin.value=location.origin;refresh();refreshTimer=setInterval(()=>{if(logged.value)refresh()},5000)})
onBeforeUnmount(()=>{clearTimeout(saveTimer);clearInterval(refreshTimer)})
async function login(){busy.value=true;loginError.value='';try{await api('/login',{method:'POST',body:{password:password.value}});password.value='';await refresh()}catch(e:any){loginError.value=e.message}finally{busy.value=false}}
async function logout(){await api('/logout',{method:'POST'});logged.value=false}
function schedule(){queued=true;notice.value='กำลังปรับ…';clearTimeout(saveTimer);saveTimer=setTimeout(save,350)}
async function save(){if(saving.value){queued=true;return}queued=false;saving.value=true;error.value='';const snapshot=JSON.stringify(draft.value);try{await api('/admin/settings',{method:'PATCH',body:JSON.parse(snapshot)});notice.value='บันทึกและส่งขึ้นจอแล้ว'}catch(e:any){error.value=e.message;notice.value='ยังไม่บันทึก'}finally{saving.value=false;if(queued||snapshot!==JSON.stringify(draft.value)){clearTimeout(saveTimer);saveTimer=setTimeout(save,350)}}}
async function moderate(id:string,status:string){try{await api(`/admin/krathongs/${id}`,{method:'PATCH',body:{status}});await refresh()}catch(e:any){error.value=e.message}}
async function clear(){try{await api('/admin/krathongs',{method:'DELETE'});confirmClear.value=false;await refresh()}catch(e:any){error.value=e.message}}
const toggles=[{key:'showNames',label:'แสดงชื่อบนกระทง'},{key:'showWishes',label:'แสดงคำอวยพร'},{key:'showQr',label:'แสดง QR บนจองาน'},{key:'accepting',label:'เปิดรับกระทงจากแขก'},{key:'moderation',label:'ตรวจคำอวยพรก่อนขึ้นจอ'}] as const
useHead({title:'ห้องควบคุมงาน • คืนจันทร์'})
</script>
<template>
<div class="admin-page"><header class="site-header"><BrandMark/><nav><span class="header-link"><span class="status-dot" :class="{offline:!connected}"/>{{connected?'ระบบพร้อมใช้งาน':'กำลังเชื่อมต่อ'}}</span><button v-if="logged" class="text-button" @click="logout"><LogOut :size="16"/> ออกจากระบบ</button></nav></header>
<div v-if="checking" class="login-panel"><p>กำลังตรวจสอบเซสชัน…</p></div>
<form v-else-if="!logged" class="login-panel" @submit.prevent="login"><span class="login-symbol"><ShieldCheck :size="30"/></span><p class="eyebrow">EVENT CONTROL ROOM</p><h1>เบื้องหลังคืนที่งดงาม</h1><p>เข้าสู่ระบบเพื่อดูแลสายน้ำของค่ำคืนนี้</p><label for="admin-password">รหัสผ่านผู้จัดงาน</label><input id="admin-password" v-model="password" type="password" autocomplete="current-password" required placeholder="รหัสผ่านผู้จัดงาน"/><p v-if="loginError" class="error-message" role="alert">{{loginError}}</p><button class="primary-button" :disabled="busy">{{busy?'กำลังเข้าสู่ระบบ…':'เข้าสู่ห้องควบคุม'}}<ArrowUpRight :size="17"/></button><NuxtLink to="/" class="text-button">กลับไปหน้าสร้างกระทง</NuxtLink></form>
<main v-else class="admin-main"><div class="admin-title"><div><p class="eyebrow">EVENT CONTROL ROOM</p><h1>ห้องควบคุมสายน้ำ</h1><p>ปรับบรรยากาศให้พอดีกับค่ำคืน ทุกการเปลี่ยนแปลงส่งตรงขึ้นจอ</p></div><NuxtLink to="/display" target="_blank" class="primary-button"><Monitor :size="17"/> เปิดจอแสดงงาน <ArrowUpRight :size="16"/></NuxtLink></div>
<div class="admin-stats"><div><Radio :size="19"/><span>กระทงทั้งหมด<strong>{{state.total}}</strong></span></div><div><ShieldCheck :size="19"/><span>รอการตรวจสอบ<strong>{{pending.length}}</strong></span></div><div><Monitor :size="19"/><span>แสดงบนจอ<strong>{{state.krathongs.length}} <small>/ {{state.settings.maxVisible}}</small></strong></span></div><div><span class="status-dot" :class="{offline:!connected}"/><span>สถานะการแสดงผล<strong class="status-text">{{draft.paused?'หยุดชั่วคราว':'กำลังล่องลอย'}}</strong></span></div></div>
<div class="admin-workspace"><section class="admin-preview"><div class="section-bar"><span><Eye :size="16"/> ภาพตัวอย่างจองาน</span><span class="live-label">LIVE PREVIEW</span></div><div class="preview-screen"><RiverScene :settings="draft" :krathongs="state.krathongs" decorative/><div class="mini-heading"><small>A THOUSAND WISHES. ONE RIVER.</small><h2>{{draft.title}}</h2><p>{{draft.subtitle}}</p></div><span v-if="!state.total" class="demo-note">กระทงตัวอย่าง · ไม่แสดงบนจอจริง</span></div><div class="preview-toolbar"><span>สัดส่วน 16:9 · รองรับการแสดงผลเต็มจอ</span><button class="outline-button" @click="draft.paused=!draft.paused;schedule()"><Play v-if="draft.paused" :size="14"/><Pause v-else :size="14"/>{{draft.paused?'เล่นต่อ':'พักการเคลื่อนไหว'}}</button></div>
<div class="qr-admin-card"><div class="small-qr"><QrCode v-if="guestUrl" :value="guestUrl" :size="112"/></div><div><p class="eyebrow">INVITE YOUR GUESTS</p><h3>หนึ่งสแกน เริ่มต้นหนึ่งความหวัง</h3><p>ใช้ QR เดียวกันได้ทุกโต๊ะในงาน</p><NuxtLink to="/qr" target="_blank" class="text-button gold">เปิดหน้าพิมพ์ QR <ArrowUpRight :size="15"/></NuxtLink></div></div>
</section>
<section class="control-panel"><div class="section-bar"><span><SlidersHorizontal :size="16"/> ตั้งค่าการแสดงผล</span><span class="save-state" aria-live="polite">{{notice||'ปรับแล้วบันทึกอัตโนมัติ'}}</span></div><div class="control-tabs"><button :class="{active:tab==='scene'}" @click="tab='scene'">ฉากและการเคลื่อนไหว</button><button :class="{active:tab==='event'}" @click="tab='event'">ข้อมูลงาน</button></div><div class="control-body"><template v-if="tab==='scene'"><div v-for="slider in sliders" :key="slider.key" class="range-field"><label :for="slider.key">{{slider.label}}<output>{{Number(draft[slider.key]).toFixed(slider.key==='maxVisible'?0:2)}}{{slider.unit}}</output></label><p>{{slider.hint}}</p><input :id="slider.key" v-model.number="draft[slider.key]" type="range" :min="slider.min" :max="slider.max" :step="slider.step" @input="schedule"/></div></template><template v-else><label for="event-title">ชื่องานบนจอ</label><input id="event-title" v-model="draft.title" maxlength="80" @input="schedule"/><label for="event-subtitle">ข้อความต้อนรับ</label><textarea id="event-subtitle" v-model="draft.subtitle" maxlength="140" rows="2" @input="schedule"/><label for="guest-url">URL สำหรับแขก / QR</label><input id="guest-url" v-model="draft.guestUrl" type="url" :placeholder="origin" @change="schedule"/><p class="field-help">ใช้ URL ที่มือถือของแขกเข้าถึงได้ เช่น HTTPS domain หรือ IP เครื่องในเครือข่ายงาน</p><div class="toggle-row" v-for="toggle in toggles" :key="toggle.key"><label :for="toggle.key">{{toggle.label}}</label><input :id="toggle.key" v-model="draft[toggle.key]" class="toggle" type="checkbox" @change="schedule"/></div></template><p v-if="error" role="alert" class="error-message">{{error}} <button class="text-button" @click="save">ลองบันทึกอีกครั้ง</button></p></div></section></div>
<section class="moderation-panel"><div class="section-bar"><span><ShieldCheck :size="17"/> กระทงและคำอธิษฐาน <small>{{items.length}} รายการล่าสุด</small></span><button class="text-button danger" @click="confirmClear=true"><Trash2 :size="15"/> ล้างข้อมูลกระทง</button></div><div v-if="!items.length" class="empty-list"><span>✧</span>ค่ำคืนนี้กำลังจะเริ่มต้น กระทงจากแขกจะแสดงที่นี่</div><div v-for="item in items" :key="item.id" class="moderation-row"><KrathongArt :base="item.base" :flower="item.flower" :country="item.country"/><div><strong>{{item.name}} <span class="badge" :class="{pending:item.status==='pending'}">{{item.status==='pending'?'รอตรวจสอบ':'บนสายน้ำ'}}</span></strong><p>{{item.wish||'ไม่ได้ระบุคำอวยพร'}}</p></div><div class="row-actions"><button v-if="item.status==='pending'" class="outline-button" @click="moderate(item.id,'approved')"><Check :size="15"/> อนุมัติ</button><button class="icon-button danger" aria-label="ลบกระทง" @click="moderate(item.id,'deleted')"><Trash2 :size="16"/></button></div></div></section>
</main>
<div v-if="confirmClear" class="modal-backdrop"><section role="alertdialog" aria-modal="true" aria-labelledby="clear-title" class="confirm-modal"><h2 id="clear-title">ล้างกระทงทั้งหมด?</h2><p>กระทงและคำอวยพรทั้งหมดจะถูกลบถาวร และนำออกจากจอทันที การตั้งค่างานยังอยู่</p><div><button class="outline-button" @click="confirmClear=false">ยกเลิก</button><button class="primary-button danger-button" @click="clear">ยืนยันลบทั้งหมด</button></div></section></div>
</div>
</template>
